"""Add a source-bound public session overlay without rebuilding older editions."""
from pathlib import Path
import hashlib,json,html,re,subprocess,zipfile
R=Path(__file__).resolve().parent;D=R/'dist';REPO=Path('/workspace/scratch/b53ad92e84b9/UD-publish')
BASE=subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip()
PIN=f'https://github.com/ud-tetra/UD/blob/{BASE}/'
OUT=D/'sources/research-record-v0.1';OUT.mkdir(parents=True,exist_ok=True)
E=lambda x:html.escape(str(x),quote=True)
def writejson(p,v):p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
def old(path):return subprocess.check_output(['git','show','HEAD:'+path],cwd=R).decode()
events=[]
for p in sorted((REPO/'events').glob('*.json')):
 d=json.loads(p.read_text());events.append({'path':str(p.relative_to(REPO)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'record':d})
records=[];copies=[];source_entries=[]
for mp in sorted((REPO/'captures').glob('*/MANIFEST.json')):
 m=json.loads(mp.read_text());cid=mp.parent.name
 ev=next((e['record'] for e in events if e['record'].get('capture_id')==cid or e['record'].get('event_id')==cid),{})
 title=cid.split('-codex-',1)[-1].rsplit('-',1)[0].replace('-',' ').capitalize()
 summary=ev.get('summary') or ev.get('description') or m.get('verification_scope') or 'Preserved repository capture; inspect the pinned manifest for its original scope.'
 if not isinstance(summary,str):summary=json.dumps(summary)
 rec={'capture_id':cid,'title':title,'date_utc':cid[:10],'original_status':m.get('status','SOURCE_STATUS_NOT_DECLARED'),'verification_scope':m.get('verification_scope','See source manifest'),'summary':summary,'manifest':{'path':str(mp.relative_to(REPO)),'sha256':hashlib.sha256(mp.read_bytes()).hexdigest(),'url':PIN+str(mp.relative_to(REPO))},'file_count':len(m['files']),'reports':[]}
 # Public research reports only. No raw notebooks, credentials or private correspondence.
 if cid>='2026-10-17':
  for f in m['files']:
   x=REPO/f['path']
   if x.parent!=mp.parent or x.suffix!='.md' or x.name not in {'README.md','REPORT.md','AUDIT.md','THEOREMS.md','TYPE_AUDIT.md','TYPED_REPAIR_v0.1.md','SESSION_SUMMARY.md','SCOPE_CLARIFICATION.md','CORRECTION.md'}:continue
   b=x.read_bytes();assert hashlib.sha256(b).hexdigest()==f['sha256'];assert len(b)==f['size_bytes']
   dest=OUT/'reports'/cid/x.name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(b)
   cf={'repository_path':f['path'],'local':'/'+str(dest.relative_to(D)),'sha256':f['sha256'],'size_bytes':len(b),'url':PIN+f['path']};copies.append(cf);rec['reports'].append(cf)
   source_entries.append({'id':f'PUBLICREC{len(source_entries)+1:03}','title':title+' — '+x.name,'group':'Session publication — source records','status':rec['original_status'],'note':'Original source status. Custody copy only; not new scientific review or promotion. '+summary,'url':cf['url'],'local':cf['local'],'sha256':cf['sha256'],'size_bytes':len(b),'content':b.decode()})
 records.append(rec)
# Exact prospective contract and public constructor code are convenient downloads.
contract=REPO/'captures/2026-10-19T130822Z-codex-parity-contract-50d3c586'
for name in ['CONTRACT.json','MANIFEST.json','VALIDATION.json','self_test.py','validate_candidate.py']:
 x=contract/name;b=x.read_bytes();dest=OUT/'parity-contract'/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(b)
 copies.append({'repository_path':str(x.relative_to(REPO)),'local':'/'+str(dest.relative_to(D)),'sha256':hashlib.sha256(b).hexdigest(),'size_bytes':len(b),'url':PIN+str(x.relative_to(REPO))})
index={'schema':'UD_PUBLIC_RESEARCH_RECORD_v0.1','publication_date':'2026-10-19','repository_commit':BASE,'scope':'All manifest-bearing public repository captures at this commit; all root research reports from 17 October onward in the selected public report classes. Source inclusion is custody, not reproof.','capture_count':len(records),'event_count':len(events),'records':records,'events':events,'public_report_copies':copies,'independent_review':'NOT_ESTABLISHED_BY_PUBLICATION','physical_promotion':0,'missing_files':['Gap2_FINAL_Finite_Genesis.png']}
writejson(OUT/'SOURCE_MAP.json',index)
summary=f'''# Public research record — 19 October 2026\n\nRepository snapshot: {BASE}. {len(records)} manifest-bearing captures and {len(events)} events are indexed. {len(source_entries)} research reports from 17 October onward are copied with exact source hashes; the earlier 26-source observation publication remains preserved. This is not a complete conversation export or independent scientific review.\n\nNative issue hierarchy and PR triage, retrospective repository integrity, scoped proof provenance, governance applicability, later-register custody, historical receipt linkage, the parity type repair, finite native W construction and prospective admission contract are now public alongside later floating estimator, preparation/clock, two-step noise and encoded projection/SVD records. Historical labels and scores remain under their original protocols.\n\nAll45 source IDs in the preserved v0.14 graph have custody routes:24 graph-declared file hashes and21 portal catalog-linked artifacts. These are distinct evidence classes. The197-object/314-edge register is a frozen edition, not a complete current proof DAG. The full custodian-ruling document is recovered, but named/signed original approval and the committed raw Gemini output remain unresolved.\n\nThe typed composite requires W: T Theta W Ic=Ic R. Exact finite source construction of a30x6 W is checked under the supplied lower-response convention; it does not derive a physical selecting law. Prospective v0.1 adds native membership, generator/Darboux tests, positive finite c, full composite and row-sum norms. Verdicts are numerical source admission, never exact radical certification. Public fixtures are constructor tests; no new blinded cohort exists.\n\nThe observation continuation includes constructor floating-estimator certificates and conditional preparation/timing and noise budgets. A new integer projection is exact on its declared encoded2^-48 ball; two actual full-factor SVD outputs certify209 sketch values above2^-24 with error<2.555e-13 on the saved record. Uniform floating SVD/phase convergence and external replay remain open. Sketch209, native1893 and hidden747 are different objects.\n\nAttached ledger v0.39 and governance v1.0 retain their source status; proposal sections1–6 are not enacted by this publication. Original source files and prior editions are preserved. Gap2_FINAL_Finite_Genesis.png is unavailable and unused.\n\nPhysical promotion:0. No new registry/CRL promotion. Independent scientific review remains separate and pending/HOLD.\n'''
(OUT/'PUBLICATION_SUMMARY.md').write_text(summary)
local=lambda cid: '/research-record/#'+cid
# Sections are hand-curated against the source reports; full source labels are retained below.
sections='''<section class="chapter" id="parity"><div class="chapter-label">01</div><div><h2>Native finite structure, with a typed parity contract.</h2><p>The finite 30×6 Darboux frame is source-recovered and checked under the declared unit metric, S₄ average and lower-response selection convention. With Q=α<sup>−1/2</sup>P<sub>evt</sub>U and α=(1+89/√8065)/2, the frame is W=(Q, AQ/√5). The source projector has rank six and A²P<sub>evt</sub>=−5P<sub>evt</sub>. The lower-response choice is still a supplied structural convention.</p><p>The repaired full composite is <strong>T Θ W I<sub>c</sub> = I<sub>c</sub> R</strong>. The embedding W is necessary for the dimensions to match. Θ²=P<sub>evt</sub> on the ambient carrier; complement parity is not selected.</p><p>The prospective v0.1 contract adds source membership, generator/Darboux checks, reciprocal positive-c admission and one induced-infinity norm. Its numeric lane is 0.001≤c≤1000, with nonfinite and overflow rejection. Successful output is <strong>NUMERICAL_SOURCE_ADMITTED</strong>, not an exact radical certificate.</p><p>Constructor fixtures passed. Historical C/D runners and score receipts remain unchanged. No new blind cohort or independent review is claimed.</p><div class="actions"><a class="text-link" href="https://github.com/ud-tetra/UD/pull/206">Finite source audit · PR #206 ↗</a><a class="text-link" href="https://github.com/ud-tetra/UD/pull/207">Contract freeze · PR #207 ↗</a><a class="text-link" href="/sources/research-record-v0.1/parity-contract/CONTRACT.json">Frozen contract ↓</a></div></div></section>
<section class="chapter" id="custody"><div class="chapter-label">02</div><div><h2>Source location is stronger; attribution remains separate.</h2><div class="table-wrap"><table><thead><tr><th>Record</th><th>Verified scope</th><th>Still open</th></tr></thead><tbody><tr><td>Preserved dependency edition v0.14</td><td>197 objects, 314 edges, 107 finite target declarations; all 45 source IDs have custody routes</td><td>Global proof DAG and rendered-text/source-version equivalence</td></tr><tr><td>45 custody routes</td><td>24 graph-declared file hashes + 21 portal catalog-linked artifacts</td><td>These recovery classes do not imply identical source-version evidence</td></tr><tr><td>Historical parity receipt chain</td><td>All eight CRL2d-manifest files and the linked CRL2c executor output recovered; full ruling document located</td><td>Named/signed original approval and committed raw Gemini output</td></tr><tr><td>Review class</td><td>Constructor, external-AI, independent-human and custodian records are distinguished</td><td>Recovery or archive merging does not establish independent proof review</td></tr></tbody></table></div><p>The earlier scoped search and every historical status remain preserved. Issue <a class="text-link" href="https://github.com/ud-tetra/UD/issues/126">#126</a> remains open. The original interactive dependency graph is still available as its frozen edition.</p><a class="text-link" href="/dependencies/">Explore the preserved graph →</a></div></section>
<section class="chapter" id="observation-continuation"><div class="chapter-label">03</div><div><h2>Floating estimates now have narrower, record-bound certificates.</h2><p>The continuation covers fixed-sketch blind spots, residual preflight, complementary sketches, actual floating estimates, operator/frame bounds, fresh seeds, preparation-specific timing, two-step source order and noise tolerance. Each report keeps its own input domain and cutoff.</p><div class="table-wrap"><table><thead><tr><th>Milestone</th><th>Scope</th><th>Boundary</th></tr></thead><tbody><tr><td>Two-step source-precision adapter</td><td>105/209 source counts at the new 2<sup>−24</sup> cutoff; conditional ideal-noise and saved floating-record certificates</td><td>Cutoffs, noise norms and ideal versus actual execution are distinct</td></tr><tr><td>Encoded-ball integer projection</td><td>Exact on the declared encoded 2<sup>−48</sup> vector-noise ball</td><td>A new integer backend; not a uniform exactness claim for legacy BLAS</td></tr><tr><td>Two actual full-factor SVD outputs</td><td>209 sketch singular values above 2<sup>−24</sup>; validated error &lt;2.555×10<sup>−13</sup> on the saved record</td><td>Uniform SVD/phase convergence and attributable external replay remain open</td></tr></tbody></table></div><p><strong>209 sketch values, 1,893 native observable directions and the 747-dimensional hidden kernel are different objects.</strong> Synthetic reconstruction/replay counts are not apparatus readings. Neither full hidden-state reconstruction nor a physical correspondence is established.</p><div class="actions"><a class="text-link" href="/observation/">Earlier 26-source observation edition →</a><a class="text-link" href="https://github.com/ud-tetra/UD/pull/208">Latest encoded projection / SVD record ↗</a></div></div></section>
<section class="chapter" id="operations"><div class="chapter-label">04</div><div><h2>Repository operations and governance remain auditable.</h2><p>Seven workstream parents, 37 original child links and four sourced blockers were recorded. The original triage covered 55 open PRs; this is a historical administrative snapshot, not the current open-PR count. Later capture PRs preserve their own merge and CI receipts. The historical main integrity failure remains visible with a retrospective receipt.</p><p>The governance crosswalk separates proposal sections 1–6, source-declared topology provisions, pending representation-rule incorporation and active repository contribution instructions. Publication does not enact the proposal or change a scientific confidence status. The attached coefficient ledger v0.39 remains a preserved source version within the existing reconciliation.</p><p>The next scientific return is attributable non-constructor review bound to exact source/code hashes. The prospective parity contract needs that challenge before a new blind campaign. The floating-estimator track separately needs an external replay and a uniform output-quality/convergence argument.</p></div></section>'''
intro=f'''<div class="page-intro"><div class="eyebrow">17–19 October 2026 · Source-bound session publication</div><h1>From captured work<br>to a reviewable record.</h1><p class="lede">Native parity, source custody and floating-estimator certificates, with the unfinished gates kept visible.</p><p>Repository snapshot <code>{BASE[:12]}</code> · {len(records)} captures · {len(events)} events. The index covers every manifest-bearing capture at this snapshot; report downloads supplement the earlier public editions.</p><div class="actions"><a class="button" href="#capture-index">Browse the evidence →</a><a class="text-link" href="/sources/research-record-v0.1/SOURCE_MAP.json">Source map & hashes ↓</a><a class="text-link" href="/sources/research-record-v0.1/RESEARCH_RECORD_v0.1.zip">Public report bundle ↓</a></div></div><aside class="callout"><strong>Development — no new registry entry · Physical promotion 0</strong><p>Exact finite checks, numerical admission, constructor replay and independent scientific review retain separate status. Original statuses below are quoted from preserved manifests; publication is not re-adjudication.</p></aside>'''
rows=[]
for rec in reversed(records):
 links=' '.join(f'<a class="text-link" href="{E(f["local"])}">{E(Path(f["repository_path"]).name)} ↓</a>' for f in rec['reports'])
 rows.append(f'''<article class="record-entry" id="{E(rec['capture_id'])}" data-record><div class="eyebrow">{E(rec['date_utc'])} UTC · {rec['file_count']} captured files</div><h3>{E(rec['title'])}</h3><p class="record-status">Original status: {E(rec['original_status'])}</p><p>{E(rec['summary'])}</p><details><summary>Provenance and verification scope</summary><p>{E(rec['verification_scope'])}</p><p class="mono">{E(rec['capture_id'])}</p><p class="mono">Manifest SHA-256: {E(rec['manifest']['sha256'])}</p></details><div class="actions">{links}<a class="text-link" href="{E(rec['manifest']['url'])}">Pinned manifest ↗</a></div></article>''')
listing=f'''<section class="chapter" id="capture-index"><div class="chapter-label">05</div><div><h2>Inspect every captured step.</h2><p>Search titles, source statuses, summaries and verification scope. Exact source files and manifests stay pinned to the repository snapshot. Earlier records are linked; selected public research reports from 17 October onward are also available here.</p><label class="record-search" for="record-query">Search the record<input id="record-query" type="search" placeholder="Try parity, clock, source custody, or review" autocomplete="off"></label><p id="record-count" role="status" aria-live="polite">{len(records)} captures</p><div id="record-results">{''.join(rows)}</div><p id="record-empty" hidden>No records match. Clear or broaden the search.</p></div></section><aside class="callout"><strong>Coverage and limits</strong><p>This is a public artifact index, not an export of hidden model state or all prior conversations. Raw internal notebooks, private correspondence and credentials are not included. Gap2_FINAL_Finite_Genesis.png remains unavailable. Existing originals and historical editions are preserved.</p></aside>'''
base=old('dist/updates/index.html')
page=re.sub(r'<main id="main">.*?</main>','<main id="main">'+intro+sections+listing+'</main>',base,flags=re.S)
page=page.replace('<title>Updates · Unified Dynamics</title>','<title>Research record · Unified Dynamics</title>').replace('data-page="updates"','data-page="research-record"').replace(' aria-current="page"','')
page=page.replace('</head>','<link rel="stylesheet" href="/assets/research-record-v0.1.css"><script src="/assets/research-record-v0.1.js" defer></script></head>')
(D/'research-record').mkdir(exist_ok=True);(D/'research-record/index.html').write_text(page)
(D/'assets/research-record-v0.1.css').write_text('''.record-entry{border-top:1px solid var(--line);padding:26px 0;overflow-wrap:anywhere}.record-entry h3{margin-top:0}.record-status{font:11px/1.6 monospace;color:var(--accent);max-width:100%;overflow-wrap:anywhere}.record-entry details{font-size:13px;color:var(--muted)}.record-entry details p{margin-top:12px}.record-entry summary{cursor:pointer}.record-entry .mono{font-size:11px;word-break:break-word}.record-search{display:grid;gap:8px;font-size:13px;margin:24px 0}.record-search input{width:100%;padding:13px;border:1px solid var(--line);background:white;color:var(--ink);border-radius:3px}.record-entry[hidden],#record-empty[hidden]{display:none}code{overflow-wrap:anywhere}''')
(D/'assets/research-record-v0.1.js').write_text('''(()=>{const q=document.querySelector('#record-query');if(!q)return;const rows=[...document.querySelectorAll('[data-record]')];const count=document.querySelector('#record-count');const empty=document.querySelector('#record-empty');const normalize=s=>s.toLowerCase().normalize('NFKC');const texts=rows.map(r=>normalize(r.textContent));const render=()=>{const terms=normalize(q.value).trim().split(/\\s+/).filter(Boolean);let n=0;rows.forEach((r,i)=>{r.hidden=!terms.every(t=>texts[i].includes(t));if(!r.hidden)n++});count.textContent=n+' of '+rows.length+' captures';empty.hidden=n>0;};q.addEventListener('input',render);render();})();''')
# Cross-link all primary navigation, preserve the home as stable navigation rather than a dated bulletin.
nav='<a href="/research-record/"><span>25</span>Research record</a>'
for f in D.rglob('*.html'):
 t=f.read_text()
 if '<nav id="navigation"' in t and nav not in t:t=t.replace('</nav>',nav+'</nav>',1)
 if f==D/'research-record/index.html':t=t.replace(nav,nav.replace('<a ','<a aria-current="page" '))
 if f==D/'index.html':
  t=re.sub(r'<aside class="callout" id="observation-session-summary">.*?</aside>','<section class="chapter" id="research-record-navigation"><div class="chapter-label">04</div><div><h2>Follow the research record.</h2><p>Browse source-bound captures, scoped verification and outstanding review gates.</p><div class="actions"><a class="text-link" href="/research-record/">Research record →</a><a class="text-link" href="/observation/">Observation programme →</a><a class="text-link" href="/updates/">Dated updates →</a></div></div></section>',t,flags=re.S)
 if f==D/'updates/index.html':
  update=f'''<article class="claim" id="research-record-v01"><div class="eyebrow">19 October 2026 · Session publication v0.1</div><h2>Native parity, source custody and actual floating certificates</h2><p>The public record now indexes all {len(records)} manifest-bearing captures and {len(events)} events through repository snapshot {BASE[:12]}. Source-selected finite W, the typed parity repair and prospective contract join the source/receipt recovery and later preparation, timing, two-step noise and encoded projection/SVD records.</p><p>Historical protocols and source statuses stay preserved. Review remains scope-specific and pending/HOLD; physical promotion 0.</p><a class="text-link" href="/research-record/">Read the session and inspect all captures →</a></article>'''
  t=t.replace('</div><article class="claim"','</div>'+update+'<article class="claim"',1)
 if f in [D/'evidence/index.html',D/'papers/index.html',D/'contribution/index.html',D/'observation/index.html',D/'dependencies/index.html']:
  t=t.replace('</main>','<aside class="callout" id="research-record-extension"><strong>Extended source-bound research record</strong><p>Later source custody, parity-contract and floating-estimator records are indexed separately. This page retains its original edition and scientific scope.</p><a class="text-link" href="/research-record/">Read the continuation and source receipts →</a></aside></main>',1)
 f.write_text(t)
sources=json.loads(old('dist/assets/sources.json'));sources+=source_entries;writejson(D/'assets/sources.json',sources)
coverage=json.loads(old('dist/assets/coverage.json'));coverage['session_publication_20261019']={'repository_commit':BASE,'captures_indexed':len(records),'events_indexed':len(events),'public_report_copies':len(source_entries),'graph_counts':'Preserved v0.14, not current-live/global completeness','source_custody':'45 routes: 24 graph-declared hashes and 21 catalog-linked artifacts','independent_review':'not established by publication','physical_promotion':0};writejson(D/'assets/coverage.json',coverage)
sitemap=old('dist/sitemap.xml');url='https://unified-dynamics-public.ben-w-mayes.chatgpt.site/research-record/'
if url not in sitemap:sitemap=sitemap.replace('</urlset>','<url><loc>'+url+'</loc></url></urlset>')
(D/'sitemap.xml').write_text(sitemap)
with zipfile.ZipFile(OUT/'RESEARCH_RECORD_v0.1.zip','w',zipfile.ZIP_DEFLATED) as z:
 for x in sorted(OUT.rglob('*')):
  if x.is_file() and x.suffix!='.zip':z.write(x,str(x.relative_to(OUT)))
print(json.dumps({'repository_commit':BASE,'captures':len(records),'events':len(events),'copied_reports':len(source_entries),'bound_copies':len(copies)}))
